if state == ExecutionState.RAW_INPUT_PROCESS:
  entities = []
  for entity in raw_input:
    entities.append({
      'typeName': entity['typeName'],
      'uniqueAttributes': {
        'qualifiedName': entity['attributes']['qualifiedName']
      }
    })

  LOGGER.debug('Entities to delete %s' % entities)
  if entities:
    request_config['json'] = entities
  else:
    stop = True

if state == ExecutionState.API_FAIL and response.status_code >= 500:
  LOGGER.debug('Atlas is unavailable. Performing retry with back-off')
  failure_handler = FailureHandler.RETRY

if state == ExecutionState.RAW_INPUT_PROCESS:
    if not raw_input:
      stop = True
    else:
      request_config['url'] = f"{{inputs.parameters.atlas-api-uri}}/glossary/terms/{raw_input[0]['glossaryTermGuid']}/assignedEntities"
      request_config['json'] = raw_input[0]["requestsData"]

if state == ExecutionState.API_POST:
    metrics.gauge('glossary_attached_gauge', 1)
    stop = True

if state == ExecutionState.API_FAIL and response.status_code >= 500:
    LOGGER.debug('Atlas is unavailable. Performing retry with back-off')
    failure_handler = FailureHandler.RETRY

if state == ExecutionState.RAW_INPUT_PROCESS:
    if not raw_input:
        stop = True
    else:
        request_config['json'] = {'entities': raw_input}

if state == ExecutionState.API_FAIL and response.status_code < 500:
    failure_handler = FailureHandler.PINPOINT

if state == ExecutionState.PINPOINT_SUCCESS:
    raise_exception = False
    failures.clear()

if state == ExecutionState.API_POST:
    atlas_response = response.json()
    # Individual typename metrics
    # We assume different types are in different files
    entities = request_config.get('json', {}).get('entities', [])
    type_name = None
    if entities:
        type_name = entities[0]['typeName']
        created_entities = len(atlas_response.get('mutatedEntities', {}).get('CREATE', []))
        total_entities = len(atlas_response.get('guidAssignments', {}))
        updated_entities = total_entities - created_entities
        LOGGER.debug('%s entities created %s and updated %s' % (type_name, created_entities, updated_entities))

        metrics.incr('entities_created,typename=%s' % type_name, created_entities)
        metrics.incr('entities_updated,typename=%s' % type_name, updated_entities)

if state == ExecutionState.OUTPUT_PROCESS:
    output = {"request": raw_input, "response": json.loads(response.text) if response is not None else None}
